<script setup lang="ts">import{computed,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{Menu,X,LayoutDashboard,Users,ShoppingCart,CalendarClock,Truck,WalletCards,ChartNoAxesCombined,Settings,UserCog,LogOut,ClipboardList}from'lucide-vue-next';import{auth}from'./auth';const open=ref(false),route=useRoute(),router=useRouter();const allLinks=[['/','Resumen',LayoutDashboard,'dashboard'],['/ventas','Ventas',ShoppingCart,'ventas'],['/entregas','Próximas entregas',Truck,'entregas'],['/clientes','Clientes',Users,'clientes'],['/cuotas','Cuotas',CalendarClock,'cuotas'],['/caja','Caja',WalletCards,'caja'],['/rentabilidad','Rentabilidad',ChartNoAxesCombined,'rentabilidad'],['/admin','Productos',Settings,'administracion'],['/usuarios','Usuarios',UserCog,'usuarios']] as const;const links=computed(()=>allLinks.filter(x=>auth.can(x[3])));async function logout(){await auth.logout();router.push('/login')}</script>
<template><RouterView v-if="route.meta.public"/><div v-else class="shell"><aside :class="{open}"><div class="brand"><img src="/brand/sportlink-logo.png" alt="Sportlink by Empire"><button @click="open=false"><X/></button></div><nav><RouterLink v-for="[to,label,icon] in links" :key="to" :to="to" @click="open=false"><component :is="icon"/>{{label}}</RouterLink><RouterLink v-if="auth.state.user?.rol==='Administrador'" to="/auditoria" @click="open=false"><ClipboardList/>Auditoría</RouterLink></nav><div class="profile"><b>{{auth.state.user?.nombre}}</b><small>{{auth.state.user?.rol}}</small><button class="logout" @click="logout"><LogOut/> Salir</button></div></aside><main><header><button class="menu" @click="open=true"><Menu/></button><div class="header-brand"><small>SPORTLINK</small><h1>Gestión de césped sintético</h1><em>by Empire</em></div><span class="online">● En línea</span></header><RouterView/></main></div></template>
